%[text]{"align":"center"} $Au\_{xx}+Bu\_{xy}+Cu\_{yy}+ ... = 0\\\\\n\nu\_{xx} = \\frac{d^2 u}{dx^2}$
%[text]{"align":"center"} $B^2-4AC \< 0     \n$ -\> elliptic
%[text]{"align":"center"} $B^2-4AC = 0     \n$ -\> parabolic
%[text]{"align":"center"} $B^2-4AC \> 0     \n$ -\> hyperbolic
%[text]{"align":"center"} String deflection: $\\frac{d^2u}{dx^2} + \\frac{d^2u}{dy^2} = f$ --\> Elliptic
%[text]{"align":"center"} Heat equation: $\\frac{dT}{dt} +\\alpha\\frac{d^2T}{dx^2} + \\alpha\\frac{d^2T}{dy^2} = 0$ --\> Parabolic
%[text]{"align":"center"} 
%[text]{"align":"center"} 
%[text]{"align":"center"} Advection equation: $\\frac{du}{dt}+c\\frac{du}{dx} = 0$
%[text]{"align":"center"} c = propagation speed, advection speed
n = 100;
x = linspace(0,10,n)';
dx = x(2)- x(1);
u = 0*x;
c = 1;
dt = 0.1;
u( x >= 1 & x <= 2) = 1;
h = plot(x,u); %[output:3c150b27]
%[text]{"align":"center"} $\\frac{u\_{i+1}-u{i}}{\\Delta t} = -c\\frac{du}{dx}$
%[text]{"align":"center"} $\\frac{u\_{j,i+1}-u\_{j,i}}{\\Delta t} = -c\\frac{u\_{j+1,i} - u\_{j-1,i}}{\\Delta x}$
%[text]{"align":"center"} With central difference:
%[text]{"align":"center"} $\\frac{u\_{j,i+1}-u\_{j,i}}{\\Delta t} = -c\\frac{u\_{j+1,i} - u\_{j-1,i}}{\\Delta x}\\\\\n\nu\_{j,i+1} - u\_{j,i} =   - c\\frac{\\Delta t}{2\\Delta x} ( {u\_{j+1,i} - u\_{j-1,i}) \\quad (1)$
%[text]{"align":"center"} 
%[text]{"align":"center"} With forward difference:
%[text]{"align":"center"} $\\frac{u\_{j,i+1}-u\_{j,i}}{\\Delta t} = -c\\frac{u\_{j+1,i} - u\_{j,i}}{\\Delta x}\\\\\n\nu\_{j,i+1} =  u\_{j,i}  - c\\frac{\\Delta t}{\\Delta x} ( {u\_{j+1,i} - u\_{j},i}) \\quad (2)$
%[text]{"align":"center"} 
%[text]{"align":"center"} With backward difference:
%[text]{"align":"center"} $\\frac{u\_{j,i+1}-u\_{j,i}}{\\Delta t} = -c\\frac{u\_{j,i} - u\_{j-1,i}}{\\Delta x}\\\\\n\nu\_{j,i+1} =  u\_{j,i}  - c\\frac{\\Delta t}{\\Delta x} ( {u\_{j,i} - u\_{j-1},i}) \\quad (2)$
%[text]{"align":"center"} 
A = zeros(n);
% Add coefficient from (1)
for ii = 2:n-1
    % Equation 1
    % A(ii,ii) = 1;
    % A(ii,ii-1) = c*dt/(2*dx);
    % A(ii,ii+1) = -c*dt/(2*dx);

    % Equation 2
    % A(ii,ii) = 1 + c*dt/dx;
    % A(ii,ii+1) = -c*dt/dx;

    % Equation 3
    A(ii,ii) = 1 - c*dt/dx;
    A(ii,ii-1) = c*dt/dx;
end

% Boundary condition du/dx(1)
A(1,1) = 1 - c*dt/dx;
A(1,end-1) = c*dt/dt;


%%
for ii = 1:500 %[output:group:31ec8be0]
    u = A*u;
    u(end) = u(1);
    h.YData = u; %[output:6869044c]
    drawnow
end %[output:group:31ec8be0]
